import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { LoginComponent } from './views/login/login.component';
import { TestComponent } from './views/test/test.component';
import { AuthGuard } from './_guards/auth.guard';
import { SignupComponent } from './views/signup/signup.component';
import { PageNotFoundComponent } from './views/page-not-found/page-not-found.component';
import {
    WalletComponent,
	WalletStartComponent,
    WalletCreateComponent,
    WalletEditComponent,
    WalletViewComponent
} from './views/wallet';
import { TransactionComponent, TransactionStartComponent, TransactionCreateComponent, TransactionViewComponent, TransactionEditComponent } from './views/transaction/transaction.component';
import {  } from './views/transaction/transaction-start/transaction-start.component';
import {  } from './views/transaction/transaction-create/transaction-create.component';
import {  } from './views/transaction/transaction-view/transaction-view.component';
import {  } from './views/transaction/transaction-edit/transaction-edit.component';

const routes: Routes = [
    {
        path: 'login',
        component: LoginComponent,
        data: { layout: 'login-layout' }
    },
    {
        path: 'signup',
        component: SignupComponent,
        data: { layout: 'login-layout' }
    },
    {
        path: 'test',
        component: TestComponent,
        canActivate: [AuthGuard],
        data: { layout: 'default-layout' }
    },
    {
        path: 'wallet',
        component: WalletComponent,
        canActivate: [AuthGuard],
        data: { layout: 'default-layout' },
        children: [
            { path: '', component: WalletStartComponent },
            { path: 'create', component: WalletCreateComponent },
            { path: ':id', component: WalletViewComponent },
            { path: 'edit/:id', component: WalletEditComponent }
        ]
    },
    {
        path: 'transaction',
        component: TransactionComponent,
        canActivate: [AuthGuard],
        data: { layout: 'default-layout' },
        children: [
            { path: '', component: TransactionStartComponent },
            { path: 'create', component: TransactionCreateComponent },
            { path: ':id', component: TransactionViewComponent },
            { path: 'edit/:id', component: TransactionEditComponent }
        ]
    },

    // page not found
    {
        path: '**',
        component: PageNotFoundComponent,
        data: { layout: 'default-layout' }
    }
];

@NgModule({
    imports: [RouterModule.forRoot(routes)],
    exports: [RouterModule]
})
export class AppRoutingModule {}
